python3 - <<'EOF'
p='src/orchestration/chatOrchestrator.test.ts'
s=open(p).read()
s=s.replace("function createErrorProvider(error: Error): AIProvider {","function createErrorProvider(error: unknown): AIProvider {",1)
old="""      await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
    });
  });
"""
new="""      await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
    });

    it('wraps an undefined rejection in an Error whose cause is the original value', async () => {
      let received: Error | undefined;
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          received = error;
        },
      };

      const orchestrator = createChatOrchestrator(createErrorProvider(undefined), promptBuilder, undefined, {hooks});
      const rejection = await orchestrator.processMessage(createSession('hello')).then(
        () => 'resolved without throwing',
        (thrown: unknown) => thrown
      );

      expect({
        rejection,
        isError: received instanceof Error,
        hasCause: received !== undefined && 'cause' in received,
        cause: received?.cause,
        message: received?.message,
      }).toEqual({rejection: undefined, isError: true, hasCause: true, cause: undefined, message: 'undefined'});
    });
  });
"""
assert old in s
s=s.replace(old,new,1)
open(p,'w').write(s)
EOF
timeout 300 npx jest --runTestsByPath src/orchestration/chatOrchestrator.test.ts -t "wraps an undefined rejection" 2>&1 | tail -30

cat >> src/orchestration/orchestratorHelpers.ts <<'EOF'

/** An Error passes through as the same instance; anything else is wrapped with the original kept as its cause. */
export function toError(thrown: unknown): Error {
  if (thrown instanceof Error) return thrown;
  return new Error(describeThrown(thrown), {cause: thrown});
}

function describeThrown(thrown: unknown): string {
  if (typeof thrown === 'string') return thrown;
  try {
    return JSON.stringify(thrown) ?? String(thrown);
  } catch {
    return String(thrown);
  }
}
EOF
